  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Kiss of the Speakers', 'passive', NULL, 'defensive', '<p>The izfiitar continuously tinkers with the myriad possibilities in which it can move or manipulate magic. The izfiitar is always Quickened and can use the extra action only to Step, Stride, or as part of Casting a Spell.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
