  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Prescient Revision', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> The izfiitar fails a check</p><hr /><p><strong>Effect</strong> The izfiitar rerolls the triggering check and takes the better result. For 1d4 rounds, it loses the effects of Kiss of the Speakers and can''t use Reshape Reality.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
