  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The izfiitar takes the appearance of any Huge or smaller creature. This doesn''t change its Speed or its attack and damage bonuses with its Strikes, but might change the damage type its Strikes deal.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'change-shape', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
