  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Rejuvenation', 'passive', NULL, 'defensive', '<p>When a ghostly mob is destroyed, it re-forms after 2d4 days within the location it''s bound to, fully healed. A ghostly mob can be permanently destroyed only if someone sets right whatever prevents the troop from resting.</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'ghost-rejuvenation', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
