  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Frightful Chorus', 'action', 2, 'offensive', '<p>The ghostly mob howls in anguish, sharing the pain of their death with any living creature that can hear them. This painful wailing forces each living creature in a 30-foot emanation to attempt a will DC 26 save or become Frightened 2 (Frightened 3 on a critical failure). Regardless of the save result, the creature is then temporarily immune to the troop''s Frightful Chorus for 1 minute.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
