  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ravenous Earthunholy', 'action', 1, 'offensive', '<p>With a single, devious thought, the urglid causes a mound of grave soil to well up at a creature''s feet. That creature must succeed at a reflex DC 30 save or become Restrained (/act escape dc=30). The restrained creature then begins sinking below the ground into a spontaneously formed grave. A creature restrained by this ability for 3 rounds is buried 6 feet deep in the ground and begins suffocating within 1 minute. A buried creature must be dug up to be freed (see Burial on page 96 of GM Core). A creature that is slain by Ravenous Earth rises as a Ghoul the next midnight.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
