  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Spirit Grasp', 'passive', NULL, 'offensive', '<p>An eseneth can Grapple incorporeal creatures despite being corporeal. The eseneth uses Athletics to Grapple incorporeal creatures as normal but can''t use Athletics for other actions against incorporeal creatures, like Shove or Trip.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
