  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Infuse Staff', 'passive', NULL, 'offensive', '<p>A shoki''s staff becomes a +1 striking staff and is treated as if it were adamantine while the shoki wields it. A shoki''s staff has Hardness 14 and HP 56 (BT 28) while possessed by the shoki and Hardness 5 and HP 20 (BT 10) while out of the shoki''s possession. A shoki whose staff is taken or destroyed can infuse a new one with an hour of work.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
