  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Soul Lock', 'action', 2, 'offensive', '<p><strong>Requirements</strong> The shoki doesn''t have a soul locked within their staff</p><hr /><p><strong>Effect</strong> The shoki attempts to capture the soul of a creature on the brink of death: an undead creature, a creature with the dying condition, or a creature that died within the last minute. The target must attempt a will DC 32 save with the following results.</p><hr /><p><strong>Critical Success</strong> The creature is unaffected and becomes temporarily immune to Soul Lock.</p>
