  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Broken Barb', 'action', 1, 'offensive', '<p><strong>Requirements</strong> A creature is Grabbed or Restrained in the nasurgeth''s jaws</p><hr /><p><strong>Effect</strong> The nasurgeth breaks a tooth off in the target, who takes 3d10 bleed and is no longer grabbed or restrained. If the target is adjacent to a surface, the tooth also pins it in place, making it Immobilized (/act escape dc=45).</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
