  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Bone Debris', 'passive', NULL, 'offensive', '<p>The bones a skeletal titan throws are large enough to clutter the battlefield. When the skeletal titan hits a creature with a bone attack, the projectile becomes difficult terrain in the square the creature occupies (or, if the creature occupies more than one square, one square it occupies of the titan''s choice). If the titan misses with a bone attack, instead a random square adjacent to the creature becomes difficult terrain.</p>', 'OGL', FALSE, '', 'bone-debris', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Mountain Slam', 'action', 3, 'offensive', '<p>The skeletal titan slams its mountain sword into the ground. The shock wave reverberates, dealing 3d12+13 bludgeoning damage to all creatures in a 20-foot line (reflex DC 33 save). A creature that fails its save is also knocked Prone.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
