  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Trample', 'action', 3, 'offensive', '<p>Huge or smaller, foot, reflex DC 33</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.Trample]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'trample', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
