  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Agonized Howl', 'action', 2, 'offensive', '<p>The unrisen howls in pain at its cursed existence. Creatures within a 30-foot emanation take 9d8 mental damage with a will DC 30 save. The unrisen can''t use Agonized Howl again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
