  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Awful Approach', 'action', 1, 'offensive', '<p><strong>Frequency</strong> once per 10 minutes</p><hr /><p><strong>Effect</strong> The unrisen reshapes its grotesque form to move swiftly. It Strides twice. Any living creature that can see the unrisen during this movement must succeed at a fortitude DC 28 save or be Sickened 1 (or Sickened 2 on a critical failure); this is a mental and visual effect.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Death Grip', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The unrisen has a living creature Grabbed or Restrained</p><hr /><p><strong>Effect</strong> The unrisen attempts to destroy its victim''s life force so it shares in the unrisen''s fate. The creature must succeed at a fortitude DC 30 save or become Doomed 1. While the curse lasts, the creature regains only half as many HP from effects with both the healing and vitality traits; if it dies, any attempt to raise it from the dead causes it to return as an unrisen. The curse ends automatically if the creature''s doomed value is reduced to 0.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
