  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Recoil from Wasted Opportunities', 'passive', NULL, 'defensive', '<p>Vermleks can''t stand the sight of a good meal presented and then swiftly taken away. Whenever a Dying creature within sight of the vermlek has its dying condition removed, the vermlek takes 1d6 mental damage.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
