  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Abandon Body', 'action', 2, 'offensive', '<p><strong>Requirements</strong> The vermlek is Inhabiting a Body</p><hr /><p><strong>Effect</strong> The vermlek crawls out of the body they are inhabiting, devouring much of the body''s remaining flesh and regaining 10 healing Hit Points in the process. The corpse they leave behind is little more than a husk.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_trait_table (name) VALUES ('manipulate') ON CONFLICT DO NOTHING;
