  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Unsettling Movement', 'passive', NULL, 'offensive', '<p>Whenever the vermlek Abandons a Body or Inhabits a Body, all creatures within 30 feet who can see the vermlek must succeed at a will DC 19 save or become Frightened 1. On a critical failure, the creature is frightened 1 and Sickened 1. Regardless of the result, creatures are immune to the same vermlek''s unsettling movement for 24 hours.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
