  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fear of Crabs', 'passive', NULL, 'interaction', '<p>If a berberoka sees a crab or crab-like creature, the berberoka must attempt a will DC 33 save. They then become immune to the sight of that creature for 10 minutes.</p><hr /><p><strong>Critical Success</strong> The berberoka is unaffected.</p>
