  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Whilring Slice', 'action', 2, 'offensive', '<p>The augur Flies or Strides, whirling as they move. The augur deals the damage of their blade Strike to each creature whose space they enter (reflex DC 16 save). Each creature is affected only once, even if the augur moves through its space multiple times.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
