  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Easy to Influence', 'passive', NULL, 'defensive', '<p>Any mental spell can affect a carbuncle, regardless of creature type limitations. Against a Suggestion spell, a carbuncle always gets an outcome one degree of success worse than it rolled on its saving throw.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
