  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Infiltration Tools', 'passive', NULL, 'interaction', '<p>A dig-widget''s face consists of a set of Infiltrator Thieves'' Tools. They can be salvaged from a destroyed dig-widget with a successful crafting DC 20 check. On a failed check, the tools are destroyed.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
