  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Mechanical Vulnerability', 'passive', NULL, 'defensive', '<p>A creature with expert proficiency in Thievery can attempt a check to /act disable-device dc=22 to damage a dig-widget. The DC is 22, and each success deals 20 untyped damage.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
