  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Drain Blood', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The drainberry bush has at least one living creature Grabbed with one of its vines</p><hr /><p><strong>Effect</strong> The bush squeezes all creatures it has grabbed, its hollow thorns piercing flesh and siphoning blood. Each creature must succeed at a fortitude DC 25 save or take 2d8+10 piercing damage and become Drained 1 (double damage and Drained 2 on a critical failure). For every creature damaged this way, a cluster of blood berries immediately grows along the bush''s branches.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
