  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Storm of Vines', 'action', 2, 'offensive', '<p>The drainberry bush makes up to four vine Strikes, each against a different target. These attacks count toward the bush''s multiple attack penalty, but the multiple attack penalty doesn''t increase until after the bush makes all these attacks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
