  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Grotesque Gift', 'passive', NULL, 'offensive', '<p>A draugr''s attacks spatter their targets with rancid flesh and rotting seaweed. A creature damaged by a draugr''s Strike must succeed at a fortitude DC 15 save or become Sickened 1 (Sickened 2 on a critical failure).</p>', 'OGL', FALSE, '', 'grotesque-gift', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
