  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Alter Dweomer', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> The dweomercat is targeted by a spell or is within the area of a spell as it''s cast</p><hr /><p><strong>Effect</strong> The dweomercat''s runelike patterns start to glow as it gains an effect related to the tradition of the triggering spell. This effect occurs before the dweomercat is affected by the triggering spell. The effect lasts for 1 minute, until the dweomercat uses this ability again, or until the dweomercat Dismisses the effect, whichever comes first.</p><ul><li><strong>Arcane</strong> Magical feedback deals 4d6 force damage to the triggering spellcaster (reflex DC 22 save).</li><li><strong>Divine</strong> The dweomercat gains a +1 status bonus to all skill checks.</li><li><strong>Occult</strong> The dweomercat becomes Invisible. This effect ends if the dweomercat uses a hostile action, in addition to the normal end conditions.</li><li><strong>Primal</strong> The dweomercat gains 10 temporary Hit Points.</li></ul>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_trait_table (name) VALUES ('arcane') ON CONFLICT DO NOTHING;
