  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Dweomer Leap', 'action', 2, 'offensive', '<p>Prerequisites The dweomercat has at least one Translocate spell remaining</p><hr /><p><strong>Effect</strong> The dweomercat casts <em>translocate</em>, then can make a melee Strike against one creature adjacent to it at the end of its teleport. If the dweomercat ends its teleport adjacent to a creature under an ongoing spell effect or who cast a spell since the dweomercat''s last turn, this does not expend a casting of <em>translocate</em>.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
