  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Pounce', 'action', 1, 'offensive', '<p>The dweomercat Strides and makes a Strike at the end of that movement. If the dweomercat began this action Hidden, it remains hidden until after this ability''s Strike.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
