  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Tilting Strike', 'reaction', NULL, 'offensive', '<p><strong>Trigger</strong> The earthen destrier tramples a creature</p><hr /><p><strong>Effect</strong> The earthen destrier makes a lance arm Strike against the creature it''s Trampling with a –5 circumstance penalty.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
