  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Strike (Jaws Only)', 'reaction', NULL, 'defensive', '<p>@Localize[PF2E.NPC.Abilities.Glossary.ReactiveStrike]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'reactive-strike', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
