  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Evisceration', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The eremite has a creature Grabbed or Restrained</p><hr /><p><strong>Effect</strong> The eremite excises flesh or bone from a creature they''ve grabbed or restrained. The target takes 6d10 persistent bleed damage.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
