  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Exquisite Pain', 'action', 1, 'offensive', '<p>An eremite''s knowledge of pressure points and pain centers is unsurpassed. A creature hit by an eremite''s melee Strikes must succeed at a fortitude DC 40 save or be Stunned 2 (Stunned 4 on a critical failure). A creature that critically succeeds is temporarily immune for 24 hours.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Focus Gaze', 'action', 1, 'offensive', '<p>The eremite stares at a creature they can see within 30 feet. The creature must immediately attempt a Will save against paralytic perfection. In addition, if the creature was already Paralyzed, on a failed save, its unnatural longing causes it to become Doomed 1. After attempting this save, the creature is then temporarily immune to Focus Gaze until the start of the eremite''s next turn.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_trait_table (name) VALUES ('concentrate') ON CONFLICT DO NOTHING;
