  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Graft Flesh', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The eremite holds a piece of flesh they collected via Evisceration</p><hr /><p><strong>Effect</strong> The eremite attaches the stolen flesh to themself. They either regain 100 Hit Points; reduce the value of their Clumsy, Drained, Enfeebled, or Stupefied condition by 3; or reduce the stage of any affliction affecting them by 3.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
