  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Shepherd''s Touch', 'passive', NULL, 'offensive', '<p>An esobok''s Strikes affect incorporeal creatures with the effects of a <em>Ghost Touch</em> property rune and deal 1d6 void damage to living creatures and 1d6 vitality damage to undead.</p>', 'OGL', FALSE, '', 'spirit-touch', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
