  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Unnerving Gaze', 'passive', NULL, 'defensive', '<p>30 feet. When a creature ends its turn in the aura, it sees the face of a departed loved one in place of the evangelist''s face. The creature must succeed at a will DC 21 save or become Frightened 2 (Frightened 3 on a critical failure).</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
