  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Focus Gaze', 'action', 1, 'offensive', '<p>The evangelist stares at a creature they can see within 30 feet. The target must immediately attempt a Will save against unnerving gaze. In addition, if the creature was already frightened, on a failed save, the evangelist is Concealed from the creature for as long as the creature remains frightened. After attempting this save, the creature is then temporarily immune to Focus Gaze until the start of the evangelist''s next turn.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
