  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Grievous Wound', 'passive', NULL, 'offensive', '<p>When the evangelist critically hits with a morningstar Strike, the target''s wound is particularly gruesome and disorienting. The creature becomes Clumsy 1, and the DC to recover from its persistent bleed damage is 17 (DC 12 when receiving especially appropriate assistance). The clumsy condition doesn''t end until the creature recovers from its persistent bleed.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
