  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Tongue Grab', 'passive', NULL, 'offensive', '<p>A creature hit by the giant frog''s tongue becomes Grabbed by the giant frog. The creature isn''t Immobilized, but it can''t move beyond the reach of the frog''s tongue. A creature can sever the tongue with a Strike against AC 13 that deals at least 2 slashing damage. This deals no damage to the frog but prevents it from using its tongue Strike until it regrows its tongue, which takes a week.</p>', 'OGL', FALSE, '', 'tongue-grab', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
