  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fiendish Telepathy 100 feet', 'passive', NULL, 'interaction', '<p>This functions as telepathy, except that the hellcat can speak mentally to any creature, regardless of language. This doesn''t grant the hellcat the ability to understand what the other creature is thinking, unless that creature also understands Diabolic.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.Telepathy]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'telepathy', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
