  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Regurgitate Gastrolith', 'action', 2, 'offensive', '<p>The irlgaunt violently regurgitates a melon-sized clot of brittle stone supernaturally infused with digestive enzymes. The stone and acid explode on impact within a range of 30 feet, dealing 7d6 piercing damage and 7d6 acid damage to creatures in a 20-foot burst (reflex DC 33 save). The irlgaunt can''t Regurgitate Gastroliths for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
