  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('All-Around Vision', 'passive', NULL, 'defensive', '<p>@Localize[PF2E.NPC.Abilities.Glossary.AllAroundVision]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'all-around-vision', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
