  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Regeneration 40 (Deactivated by Electricity or Fire)', 'passive', NULL, 'defensive', '<p>@Localize[PF2E.NPC.Abilities.Glossary.Regeneration]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'regeneration', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Furious Roar', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> The jotund troll takes electricity or fire damage</p><hr /><p><strong>Effect</strong> The jotund troll uses their Cacophonous Roar and, if they''re aware of the damage''s source, can Stride toward it. If the jotund troll has persistent fire damage, they attempt a flat DC 15 to remove it.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Head Regrowth', 'passive', NULL, 'defensive', '<p>A jotund troll''s regeneration can regrow severed heads. After regaining Hit Points from regeneration, the jotund troll attempts a flat DC 8. On a success, one missing head is fully restored; on a critical success, two missing heads are fully restored. If a jotund troll loses their last remaining head, they die immediately.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Heads', 'passive', NULL, 'defensive', '<p>A jotund troll gains an extra reaction per round for each of their heads beyond the first, which they can use only to make Reactive Strikes with their jaws or to Fast Swallow. They can''t use more than 1 reaction for the same triggering action, even if a creature leaves several squares within their reach, and must use a different head for each Reactive Strike. Whenever one of the jotund troll''s heads is severed, the troll loses 1 of their extra reactions per round.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Strike', 'reaction', NULL, 'defensive', '<p>@Localize[PF2E.NPC.Abilities.Glossary.ReactiveStrike]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'reactive-strike', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Cacophonous Roar', 'action', 1, 'offensive', '<p>The jotund troll roars from all their heads, mystically distorting the listener''s mind. Each non-troll creature in a 100-foot emanation must attempt a will DC 34 save.</p><hr /><p><strong>Critical Success</strong> The creature is unaffected and is temporarily immune for 24 hours.</p>
