  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fast Swallow', 'reaction', NULL, 'offensive', '<p><strong>Trigger</strong> The jotund troll Grabs a creature with their jaws</p><hr /><p><strong>Effect</strong> The troll uses Swallow Whole.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
