  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ravenous Jaws', 'action', 2, 'offensive', '<p>The jotund troll makes a number of jaws Strikes up to their number of heads, each against a different target. These attacks count toward the troll''s multiple attack penalty, but the penalty doesn''t increase until after the jotund troll makes all of these attacks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
