  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The kelpie can take on the appearance of any Medium or Large animal of an equine nature (such as a Horse, Hippocampus, or Pony), or any Small or Medium humanoid. This doesn''t change its Speeds or its attack and damage modifiers with its Strikes.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'change-shape', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
