  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Solidify Mist', 'action', 1, 'offensive', '<p>The mist stalker makes its mist cloud congeal, causing the aura to be difficult terrain until the start of the mist stalker''s next turn. In addition, the mist stalker can make the mist even thicker around a single Medium or smaller creature within the cloud. The creature must succeed at a reflex DC 20 save or become Immobilized until it Escapes or is no longer in the mist cloud''s emanation.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
