  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Gatekeeper Aura', 'passive', NULL, 'defensive', '<p>60 feet. A creature that uses a teleportation ability within the aura''s emanation or enters it via a teleportation ability must succeed a will DC 38 save or become Sickened 1 and have its destination changed to a point of the radiant warden''s choosing within the aura. On a successful save, the creature arrives as intended but is still sickened 1.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_trait_table (name) VALUES ('aura') ON CONFLICT DO NOTHING;
