  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Radiant Blast', 'action', 2, 'offensive', '<p>The radiant warden releases a 50-foot cone of bright energy that deals 10d12 force damage (reflex DC 38 save). The radiant warden can''t use Radiant Blast for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
