  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Radiant Blow', 'passive', NULL, 'offensive', '<p>When a creature is hit by the radiant warden''s hammer Strike, a flash of radiant energy attempts to anchor the creature in place. The creature must attempt a will DC 38 save; on a failure, the creature can''t use any teleportation effects for 1 minute. On a critical failure, the creature is also permanently Blinded.</p>', 'OGL', FALSE, '', 'radiant-blow', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
