  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ravenous Repast', 'action', 3, 'offensive', '<p><strong>Frequency</strong> once per day</p><hr /><p><strong>Effect</strong> The ravener husk makes a jaws Strike against a deceased creature that has been dead no longer than 1 minute, was holy, and was at least level 15 in life. The ravener attempts a flat DC 5; if successful, they transform back into a ravener with 1 Hit Point in their soul ward.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
