  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Discorporate', 'free', NULL, 'defensive', '<p><strong>Trigger</strong> The ravener takes excess damage to their soul ward but still has at least 51 Hit Points in their soul ward</p><hr /><p><strong>Effect</strong> The ravener draws deeply into their soul ward, discorporating their body into soul energy to escape. They take50 untyped damage to their soul ward and their physical body vanishes, reappearing 1d4 hours later in a random location within 1 mile from the location where they used Discorporate.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
