  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Consume Soul', 'free', NULL, 'offensive', '<p><strong>Trigger</strong> A living creature within 30 feet of the ravener dies</p><hr /><p><strong>Effect</strong> The ravener tears the creature''s soul from its body with their maw and gulps it down. The dying creature must attempt a fortitude DC 44 save with the same DC as the ravener''s breath ability.</p><hr /><p><strong>Critical Success</strong> The creature is unaffected.</p>
