  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Void Breath', 'action', 2, 'offensive', '<p>The ravener breathes a blast of necrotic flame that deals 20d6 fire damage plus 4d6 persistent void damage (reflex DC 44 save). A creature that fails its save is also Drained 1 (or Drained 2 on a critical failure). If a creature is drained by the ravener''s Void Breath, the ravener''s soul ward gains 5 HP. The ravener can''t use Void Breath again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
