  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Void Child', 'passive', NULL, 'defensive', '<p>Sceaduinar have neither souls nor the ability to create. A sceaduinar is immune to effects that target a soul (such as Seize Soul or a Resurrect ritual) or that require knowledge of a creature''s identity (such as Scrying), and critically fails Crafting checks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
