  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Burning Rush', 'action', 2, 'offensive', '<p>The striding fire stretches out its legs to an impossible length, propelling it forward. The striding fire Strides up to double its Speed in a straight line. Its movement during this Stride doesn''t trigger reactions. Any creature the striding fire was adjacent to at any point during this Stride must attempt a reflex DC 24 save. If it critically fails, it''s knocked Prone by a wave of heated air. The striding fire can''t use Burning Rush for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
