  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Elemental Assault', 'action', 2, 'offensive', '<p>Elemental magic fills the dune dancer''s body or weapon. The dune dancer chooses one element and makes a melee Strike. The Strike deals an additional 1d4 damage of the indicated type and has the trait corresponding to the element:</p><ul><li><p><strong>Air</strong> electricity</p></li><li><p><strong>Earth</strong> bludgeoning</p></li><li><p><strong>Fire</strong> fire</p></li><li><p><strong>Metal</strong> slashing</p></li><li><p><strong>Water</strong> cold</p></li><li><p><strong>Wood</strong> vitality</p></li></ul>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
