  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Poison Gasp', 'action', 1, 'offensive', '<p>The tatzlwyrm belches a puff of poisonous vapor into the face of an adjacent creature, which must attempt a fortitude DC 15 save; the creature takes a –2 circumstance penalty to this save if it''s Grabbed or Off-Guard. The tatzlwyrm can''t use Poison Gasp again for 2 rounds.</p><hr /><p><strong>Critical Success</strong> The target is unaffected.</p>
