  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Terrifying Gaze', 'passive', NULL, 'defensive', '<p>30 feet. When a creature ends its turn in the aura, it must attempt a will DC 30 save. If the creature fails, it becomes Frightened 2. The creature is then temporarily immune to terrifying gaze (but not Focus Gaze) for 24 hours.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
