  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Draining Strike', 'passive', NULL, 'offensive', '<p>When a thanadaemon damages a living creature with a melee Strike, the creature must succeed at a fortitude DC 33 save or become Drained 1. Further damage dealt by the thanadaemon increases the drained condition value by 1 on a failed save, to a maximum of Drained 4.</p>', 'OGL', FALSE, '', 'draining-strike', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
