  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Focus Gaze', 'action', 1, 'offensive', '<p>The thanadaemon glares at a single creature they can see within 30 feet. If the target wasn''t already Frightened, they must immediately attempt a will DC 33 save against the thanadaemon''s terrifying gaze. If the target was already frightened, they must attempt a will DC 33 save or become Fleeing for 1d4 rounds; this second effect has the incapacitation trait. After attempting its save, the creature is temporarily immune to this ability until the start of the thanadaemon''s next turn.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
