  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Voidsense', 'passive', NULL, 'interaction', '<p>The dragon can taste animating void energy, allowing them to sense creatures with void healing as a precise sense. It can also sense incorporeal creatures with void healing, like shadows, when they are inside solid objects.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
