  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Necrotic Decay', 'passive', NULL, 'defensive', '<p>When an urdefhan dies, their translucent flesh quickly rots away and sublimates into a foul-smelling gas that fills a 5-foot emanation around the body. This gas deals 3d6 void damage to creatures in this area as their flesh curdles and rots (fortitude DC 17 save).</p>', 'OGL', FALSE, '', 'necrotic-decay', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
