  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ravenous Attack', 'action', 2, 'offensive', '<p>The urdefhan makes one rhoka sword Strike and one jaws Strike against a single creature. Their multiple attack penalty doesn''t increase until after both attacks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
