  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Hallucinatory Brine', 'passive', NULL, 'offensive', '<p>A creature hit by the vaspercham''s Strikes or Mindwarping Tide must attempt a fortitude DC 38 save. On a failure, the creature is overwhelmed with phantasmal visions, becoming Confused for 1 round (1 minute on a critical failure).</p>', 'OGL', FALSE, '', 'hallucinatory-brine', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
