  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Slow Metabolism', 'passive', NULL, 'interaction', '<p>A water orm can go for 10 years without feeding. Beyond this limit, the water orm''s hunger causes it to become Slowed 1 but doesn''t otherwise impact its lifespan. A water orm that''s slowed as a result of starvation can remove this condition by using Swallow Whole to gulp down a meal.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
