  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Abeyance Rift', 'passive', NULL, 'defensive', '<p>If an arboreal archive dies unexpectedly before passing on their knowledge in a succession ritual, the amassed lore within their roots and boughs explodes out in a shock wave that deals 8d10 mental damage to creatures within 30 feet (will DC 32 save) before dissipating; those who fail also fall Prone.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
