  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Death Blaze', 'passive', NULL, 'defensive', '<p>When the vanguard dies, their body combusts in a blaze of fire and armor shrapnel. All creatures within a 10-foot  take 3d6 fire 3d6piercing|options:area-damage]{3d6 fire damage and 3d6 piercing damage} (reflex DC 19 save). The vanguard''s armor is destroyed in the blaze, but their other gear is unaffected and left in a pile where they died.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
