  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Call to Arms', 'action', 1, 'offensive', '<p>Each caligni within 30 feet of the vanguard gains the Reactive Strike reaction until the end of the vanguard''s next turn. Once a caligni has used this Reactive Strike, that caligni is temporarily immune to the same vanguard''s Call to Arms for 10 minutes.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
