  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Desert-Adapted', 'passive', NULL, 'interaction', '<p>A camel is well-adapted to heat and deserts. If allowed to drink and eat its fill, (roughly 40 gallons), it can Subsist for 2 weeks without needing to attempt Survival checks, and it treats environmental heat as if it was one step less severe.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
