  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Camel Spit', 'passive', NULL, 'offensive', '<p>To drive away enemies, the camel spits the partially digested contents of its stomach at a creature within 10 feet.</p>
