  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Relentless', 'passive', NULL, 'defensive', '<p>The titan is as ever-moving as ocean waves. They''re permanently Quickened, and the extra action can be used only to Stride, Strike, or Sustain a Spell, or as one of the actions necessary to cast Dispel Magic.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Roiling Rebuke', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature within 200 feet targets the titan with or includes the titan in the area of an attack, spell, or other effect</p><hr /><p><strong>Effect</strong> The titan makes a benthic wave Strike against the triggering creature. If the Strike hits, the titan disrupts the triggering action.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
