  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Whispers of Discord', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature within 60 feet is targeted by a spell that would restore Hit Points or provide a status bonus (the deimavigga automatically recognizes such effects)</p><hr /><p><strong>Effect</strong> The deimavigga whispers disturbing lies, audible only to the target, to shake the target''s faith in the spell''s caster. The target must attempt a will DC 38 save.</p><hr /><p><strong>Critical Success</strong> The target disbelieves the lies and receives the intended benefit of the spell; the target becomes temporarily immune to Whispers of Discord for 24 hours.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Boundless Reach', 'passive', NULL, 'offensive', '<p>A deimavigga''s razor-sharp claws can slice through reality, allowing them to make claw Strikes and use spells with a range of touch against any creature they can see directly or via magic. A creature targeted in this way can retaliate until the start of the deimavigga''s next turn; it can target the devil''s claws as if the devil were physically present and adjacent to the target, though the claws are Concealed.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
