  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The deimavigga can take on the appearance of any humanoid. This doesn''t change their Speed or attack and damage bonuses with Strikes but might change the damage type their Strikes deal (typically to bludgeoning).</p>
  INSERT INTO pf_trait_table (name) VALUES ('concentrate') ON CONFLICT DO NOTHING;
