  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Whisper Earworm', 'action', 1, 'offensive', '<p>The deimavigga whispers a terrifying multiversal truth to one adjacent creature, shaking its faith in reality and divinity. The target must attempt a will DC 38 save. Celestials and fiends gain a +2 status bonus to this save.</p><hr /><p><strong>Critical Success</strong> The target is unaffected and temporarily immune to Whisper Earworm for 24 hours.</p>
