  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sand Spin', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The desert giant is standing in sandy terrain</p><hr /><p><strong>Effect</strong> The desert giant spins around and stirs up loose sand in a 10-foot emanation. Until the beginning of the giant''s next turn, creatures in the area are Concealed, and other creatures are concealed to them.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sandwalking', 'passive', NULL, 'offensive', '<p>Desert giants have adapted to the loose sands of the desert and can move across them with ease. Desert giants ignore non-magical difficult terrain and uneven ground caused by sand.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Scimitar Blitz', 'action', 2, 'offensive', '<p>The desert giant Strides up to their Speed, Striking once with each of their scimitars at any point during the movement.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
