    INSERT INTO pf_item_table (foundry_id, name, bulk, base_item, category, description, hardness, hp, level, price, usage, item_group, item_type, is_derived, material_grade, material_type, number_of_uses, license, remaster, source, rarity, size, status) VALUES ('L64zgCoVQOuRPX1o', 'Doubling Rings', 0.0, NULL, NULL, '<p>This item consists of two magically linked rings: an intricate, gleaming golden ring with a square-cut ruby, and a thick, plain iron ring. When you wield a melee weapon in the hand wearing the golden ring, the weapon''s fundamental runes are replicated onto any melee weapon you wield in the hand wearing the iron ring. (The fundamental runes are <em>weapon potency</em> and <em>striking</em>, which add an item bonus to attack rolls and extra weapon damage dice, respectively.) Any fundamental runes on the weapon in the hand wearing the iron ring are suppressed.</p>
