  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Tremorsense (Imprecise) within their entire bound yard', 'passive', NULL, 'interaction', '<p>@Localize[PF2E.NPC.Abilities.Glossary.Tremorsense]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'tremorsense', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
