  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Master of the Yard', 'passive', NULL, 'interaction', '<p>The dvorovoi helps or causes trouble in the yard, milking or scaring cows, protecting or scattering tools, and so forth. A yard so blessed never encounters random accidents such as fires, and any checks to Craft, Earn Income, Repair, or Subsist in the yard receive a +2 circumstance bonus. If the dvorovoi is unfriendly, such checks take a –2 circumstance penalty instead, as the dvorovoi hides things, makes noise when people try to sleep, tangles weaving, and otherwise makes life a misery. A domovoi must spend a week in a place before these benefits occur.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('At-Will Spells', 'passive', NULL, 'interaction', '<p>@Localize[PF2E.NPC.Abilities.Glossary.AtWillSpells]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'at-will-spells', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
