  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Shy', 'passive', NULL, 'defensive', '<p>A dvorovoi is naturally Invisible while within sight of their bound home. The dvorovoi can become visible, or even selectively visible-allowing some people to see them.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
