  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Titanic Grasp', 'action', 1, 'offensive', '<p>The titan makes a fist Strike against a creature affected by their impossible stature, even if it''s outside of the titan''s normal reach. On a hit, the titan automatically Grabs the creature and, if out of their reach, pulls it within reach.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
