  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Frightful Presence', 'passive', NULL, 'defensive', '<p>90 feet will DC 32. Creatures with the animal, fungus, or plant trait take a –2 circumstance penalty to the save.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.FrightfulPresence]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'frightful-presence', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
