  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Azure Swarm Breath', 'action', 2, 'offensive', '<p>The dragon unleashes a swarm of insects that deals 14d6 piercing damage in a 40-foot cone (reflex DC 34 save) before dispersing. A creature that critically fails takes 2d6 persistent poison damage. The dragon can''t use Azure Swarm Breath again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
