  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Draconic Momentum', 'passive', NULL, 'offensive', '<p>The dragon recharges their Azure Swarm Breath whenever they score a critical hit with a Strike.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Draining Blight', 'action', 2, 'offensive', '<p><strong>Frequency</strong> once per day</p><hr /><p><strong>Effect</strong> The dragon draws moisture from the living creatures surrounding them to heal their own wounds. Each living creature in a 30-foot emanation takes 7d10 void damage (fortitude DC 34 save). Creatures made entirely of water and plant creatures use the outcome one degree of success worse than they rolled. The dragon regains Hit Points equal to half of the highest damage a single creature takes from this effect. All non-creature plant life in the area withers and dies, eliminating non-magical undergrowth and any associated difficult terrain, cover, and concealment.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
