  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Abandon Puppet', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The incutilis is attached to a puppet</p><hr /><p><strong>Effect</strong> The incutilis abandons its puppet, detaching and separating from its nervous system. If the puppet is still alive, it''s Unconscious and temporarily immune to that incutilis''s Puppetmaster ability for 24 hours.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
