  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Strike (Special)', 'reaction', NULL, 'defensive', '<p>If the triggering creature is frightened, the kimenhul can make two claw Strikes against the creature instead of one Strike.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ReactiveStrike]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'reactive-strike', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
