  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Frightening Flurry', 'action', 2, 'offensive', '<p>The kimenhul makes one jaws Strike and two claw Strikes against a single target, in any order. The target becomes Frightened with a condition value equal to the number of Strikes that hit it, to a maximum of frightened 3 if all three Strikes hit.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
