  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The kitsune trickster transforms into the tailless form of a specific Medium human. The tailless form can''t be altered and resembles the kitsune''s fox-like humanoid form. While the kitsune trickster''s alternate form is a Medium human, some kitsune have tailless forms of other humanoids, or a fox alternate form.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'change-shape', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
