  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Command Thrall', 'free', NULL, 'offensive', '<p><strong>Requirements</strong> One of the nosferatu''s thralls is present and can hear the nosferatu</p><hr /><p><strong>Effect</strong> The nosferatu gives a single command to one of their thralls, which the thrall follows to the best of its ability during its next turn.</p>', 'ORC', TRUE, 'Pathfinder Monster Core 2', 'vampire-nosferatu-command-thrall', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
