  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Spray Pus', 'action', 1, 'offensive', '<p>The nucol flexes one of its infected wounds, releasing a spray of pus in a 15-foot  or targeting an individual creature within 30 feet. A creature targeted or in the area is exposed to nervous consumption.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
