  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Entangling Train', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature moves adjacent to the pakalchi</p>
