  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The procyal can transform only into a specifc individual Small or Medium humanoid that they''ve met at least once. They can''t transform into a generic member of a given ancestry.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'change-shape', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
