  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Mass Wriggle', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> The rat snake swarm takes damage from a melee Strike</p><hr /><p><strong>Effect</strong> Snakes slither up and around the creature''s weapon and limbs. The target must succeed at a will DC 15 save or become Frightened 1.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
