  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Drain Blood', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The sabosan has a creature Grabbed or Restrained</p><hr /><p><strong>Effect</strong> The sabosan drains blood from the creature. The creature must succeed at a fortitude DC 22 save or become Drained 1. The sabosan gains a number of temporary Hit Points equal to the number of Hit Points lost by the creature due to its drained condition.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
