  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fell Shriek', 'action', 2, 'offensive', '<p>The sabosan emits a deafening cry in a 30-foot cone. Non-sabosan creatures in this area must each succeed at a fortitude DC 22 save or be Deafened for 1 minute.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
