  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Liquefy', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> The dragon takes fire damage</p><hr /><p><strong>Effect</strong> The dragon turns momentarily into water while maintaining their shape. They gain fire resistance 10, including against the triggering effect, until the end of their next turn.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
