  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Black Water Breath', 'action', 2, 'offensive', '<p>The dragon shoots a ball of water that deals 9d6 bludgeoning damage in a 20-foot burst within 40 feet (reflex DC 26 save). All non-magical fire in the radius is extinguished. The dragon can''t use Black Water Breath again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
