  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Blatant Liar', 'passive', NULL, 'defensive', '<p>While all divs delight in lying, sepids are compulsive and predictable liars who always do the opposite of what they claim they''ll do. If a sepid is ever forced or compelled to tell the truth, they take 4d8 mental damage.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Deflecting Lie', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature hits the sepid with a ranged Strike or a ranged spell attack roll</p><hr /><p><strong>Effect</strong> The sepid lies in an attempt to divert the attack. They roll a deception check against the triggering creature''s Perception DC. On a success, if the triggering attack roll was a success, it becomes a failure, and if the triggering attack roll was a critical hit, it becomes a normal success.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Strike', 'reaction', NULL, 'defensive', '<p>A sepid gains an extra reaction each round that they can use only to make a Reactive Strike.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Rain of Debris', 'action', 2, 'offensive', '<p>The sepid calls forth a hail of stone, wood, metal, and similar debris in a 40-foot , dealing 10d6 bludgeoning 5d6spirit|options:area-damage]{10d6 bludgeoning damage and 5d6 spirit damage}. Each creature in the area other than the sepid must attempt a reflex DC 31 saving throw.</p>
