  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Divine Lightning', 'passive', NULL, 'offensive', '<p><strong>Requirements</strong> The dragon worships a deity whose sanctification entry lists "holy"</p><hr /><p><strong>Effect</strong> The sky dragon channels divine power through its attacks, making them more effective against the unholy. Any electricity damage it deals becomes spirit damage against unholy creatures.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
