  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Countered by Fire', 'passive', NULL, 'defensive', '<p>If the sky dragon takes fire damage, the elemental magic of metal within them is tempered. Until the end of their next turn, they take a –1 circumstance penalty to attack rolls and AC, and their jaws Strikes don''t deal electricity damage. This limitation ends if the dragon uses Steel Lightning Breath.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fed by Earth', 'passive', NULL, 'defensive', '<p>When a sky dragon is targeted by an earth spell or effect, they crystallize the minerals in their scales to create a light-bending or light-scattering layer for camouflage. For 1 minute, the dragon is Concealed while flying.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
