  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Transparent', 'passive', NULL, 'interaction', '<p>A slithering pit is so clear it''s difficult to spot. A successful perception DC 30 check is required to notice a stationary slithering pit, and a creature must be Searching to attempt this check.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Breach Vulnerability', 'passive', NULL, 'defensive', '<p>Ingesting an extradimensional space like that found in a Spacious Pouch deals 6d8 force damage to the slithering pit and its occupants. The slithering pit then immediately uses Out You Go.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
