  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Dimensional Pit', 'action', 2, 'offensive', '<p>The slithering pit opens an extradimensional, 20-foot-deep pit that covers its own space and all adjacent squares unless they''re walls or similar blocking terrain.</p>
  INSERT INTO pf_trait_table (name) VALUES ('extradimensional') ON CONFLICT DO NOTHING;
