  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Flurry of Pods', 'action', 2, 'offensive', '<p>The slithering pit makes a single pseudopod Strike against each target within range it doesn''t already have Grabbed. These attacks count toward the slithering pit''s multiple attack penalty, but the penalty doesn''t increase until after all of these attacks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
