  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Gleaming Armor', 'action', 1, 'offensive', '<p><strong>Frequency</strong> once per hour</p><hr /><p><strong>Effect</strong> The dragon''s armor glows with a golden light. The dragon gains a +2 status bonus to AC and resistance 15 to acid, cold, electricity, fire, and sonic damage. Each enemy in a 20-foot emanation must succeed at a fortitude DC 36 save or be Dazzled. All these effects last until the end of the dragon''s next turn.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
