  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Violent Retort', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature within the sovereign dragon''s reach critically hits the dragon</p><hr /><p><strong>Effect</strong> The sovereign dragon makes a claw or tail Strike against the creature, after applying all the effects of the critical hit to the dragon.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
