  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The dragon takes on the appearance of any Small or Medium humanoid. This doesn''t change its Speed or attack and damage bonuses with its Strikes, but might change the damage type its Strikes deal (typically to bludgeoning).</p>
  INSERT INTO pf_trait_table (name) VALUES ('concentrate') ON CONFLICT DO NOTHING;
