  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sovereign''s Rebuke', 'action', 2, 'offensive', '<p>The dragon unleashes a roar charged with psychic energy, dealing 16d6 mental damage in a 40-foot cone (will DC 36 save). The dragon can''t use Sovereign''s Rebuke again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
