  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Reactive Strike', 'reaction', NULL, 'defensive', '<p>The titan can use their Reactive Strike when a creature within their reach uses a concentrate action, in additional to its normal trigger. They disrupt actions on any hit, not just a critical hit—including triggering concentrate actions.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ReactiveStrike]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'reactive-strike', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Godslayer', 'free', NULL, 'offensive', '<p><strong>Trigger</strong> The titan damages a creature capable of using divine spells or abilities</p><hr /><p><strong>Effect</strong> The creature must attempt a will DC 45 save.</p><hr /><p><strong>Critical Success</strong> The creature is unaffected.</p>
  INSERT INTO pf_trait_table (name) VALUES ('divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_trait_action_association_table (action_id, trait_id) VALUES (v_action_id, 'divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Titanic Charge', 'action', 2, 'offensive', '<p>The titan Strides twice and makes a melee Strike. If the Strike hits, the titan can cast Earthquake centered on the target as a free action.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Trample', 'action', 3, 'offensive', '<p>Huge or smaller, foot, reflex DC 45</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.Trample]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'trample', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Void Explosion', 'passive', NULL, 'offensive', '<p>If the titan''s void chunk Strike isn''t a critical failure, the chunk explodes, dealing 10d6 void damage to all creatures in a 20-foot burst (reflex DC 45 save).</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Wide Cleave', 'action', 2, 'offensive', '<p>The titan makes a melee weapon Strike against each foe within their reach. This counts as three attacks for the titan''s multiple attack penalty, but the penalty doesn''t increase until all attacks have been made.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
