  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Flailing Thrash', 'action', 2, 'offensive', '<p>The tikbalang makes two fist Strikes, with each Strike dealing an extra 1d6 untyped damage against creatures grabbing or Grabbed or Restrained by the tikbalang. The multiple attack penalty doesn''t increase until after both attacks.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
