  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Rib Skewer', 'action', 1, 'offensive', '<p>The tyrannosaurus skeleton bends down, attempting to skewer one adjacent creature on one of its massive ribs. The creature takes 2d10+9 piercing damage (reflex DC 28 save). If the creature fails its save and is Medium or smaller, it''s also impaled and stuck to the rib. It moves with the skeleton and takes 2d6 bleed until it either Escapes or someone uses /act force-open dc=28 to break the rib (either is DC 28).</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
