  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Eclipse', 'action', 2, 'offensive', '<p><strong>Effect</strong> The tzitzimitl casts darkness and drains the heat and warmth from the darkness spell''s area. Each creature within the spell''s area must attempt a fortitude DC 41 save.</p><hr /><p><strong>Critical Success</strong> The creature takes 4d8 cold damage.</p>
