  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sweltering Heat', 'passive', NULL, 'defensive', '<p>10 feet. Each creature that ends its turn in the aura must succeed at a fortitude DC 28 saving throw or become Fatigued while it remains in the aura.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
