  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Adamantine Claws', 'action', 1, 'offensive', '<p><strong>Frequency</strong> one per hour</p><hr /><p><strong>Effect</strong> The dragon infuses their body with adamantine. For the next minute, their melee Strikes are treated as adamantine and ignore half the Hardness of any object hit.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
