  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Constrict', 'action', 1, 'offensive', '<p>2d8+10 bludgeoning, fortitude DC 30</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.Constrict]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'constrict', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
