  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Countered by Water', 'passive', NULL, 'defensive', '<p>If the underworld dragon takes damage from a spell with the cold or water trait, the elemental magic of fire within them is momentarily dampened. Until the end of their next turn, they take a –1 circumstance penalty to attack rolls, and their jaws Strikes don''t deal fire damage. This limitation ends if the dragon uses Exploding Red Breath.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Fed by Wood', 'passive', NULL, 'defensive', '<p>When an underworld dragon is struck by a weapon made primarily of wood or affected by a spell with the plant or wood trait, the dragon''s internal fiery essences are stoked with the added fuel. Their Exploding Red Breath recharges, and the fire damage from the dragon''s jaws deals an additional die of damage until the end of the dragon''s next turn.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Frightful Presence', 'passive', NULL, 'defensive', '<p>90 feet will DC 35</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.FrightfulPresence]</p>', 'ORC', TRUE, 'Pathfinder Monster Core', 'frightful-presence', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
