  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Exploding Red Breath', 'action', 2, 'offensive', '<p>The dragon breathes a blast of fire that explodes in a 30-foot burst within 60 feet, dealing 14d6 fire damage (reflex DC 39 save). Creatures that fail the save also take 3d6 persistent fire damage. The dragon can''t use Exploding Red Breath again for 1d4 rounds.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
