  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Scorch Earth', 'action', 2, 'offensive', '<p>The dragon plunges their body into the ground, Burrows up to their burrow Speed, and then scorches the land within a 60-foot emanation. Creatures underground or on the surface in the area take 8d6 fire damage (fortitude DC 37 save). A creature that critically fails also becomes Enfeebled 1 for 1 minute.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
