  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Shadowplay', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The wayang''s last action was a melee Strike that damaged their opponent</p><hr /><p><strong>Effect</strong> The wayang attempts to Tumble Through the opponent''s space, with a +2 circumstance bonus to the Acrobatics check. If they succeed, the wayang leaves a shadowy afterimage in their original space, which provides flanking against the opponent until the beginning of the wayang''s next turn (usually making them Off-Guard to the wayang''s melee attacks).</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
