  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Droning Distraction', 'action', 1, 'offensive', '<p><strong>Effect</strong> The wihsaak beats its wings rapidly, creating a buzzing drone that numbs creatures'' minds. Each creature within 100 feet must attempt a will DC 23 save. They are then temporarily immune for 1 minute.</p><hr /><p><strong>Success</strong> The creature is unaffected.</p>
