  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ethereal Step', 'action', 1, 'offensive', '<p>The ether spider shifts to either the Ethereal Plane or the Universe. The ether spider can remain on the Ethereal Plane indefinitely without ill effect. While there, it can see clearly into the Universe with a range of 60 feet. On its first round in an encounter, the ether spider can use this ability once as a free action.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
