  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Ethereal Web Trap', 'passive', NULL, 'offensive', '<p>A creature hit by the ether spider''s web attack is Immobilized and stuck to the nearest surface (Escape DC 22).</p>', 'OGL', FALSE, '', 'ethereal-web-trap', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
