  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Web Burst', 'action', 2, 'offensive', '<p><strong>Frequency</strong> once per day</p><hr /><p><strong>Effect</strong> The ether spider flings a gout of stored webs in a 30-foot cone. These webs can pass between the Universe and the Ethereal Plane. Each creature in the area is Immobilized, as ethereal web trap, unless it succeeds at a reflex DC 22 save.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
