  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Protean Anatomy 10', 'passive', NULL, 'defensive', '<p>A protean''s vital organs shift and change shape and position constantly. Immediately after the protean takes acid, electricity, or sonic damage, it gains the listed amount of resistance to that damage type. This lasts for 1 hour or until the next time the protean takes damage of one of the other types (in which case its resistance changes to match that type), whichever comes first. The protean is immune to polymorph effects unless it is a willing target. If Blinded or Deafened, the protean automatically recovers at the end of its next turn as new sensory organs grow to replace the compromised ones.</p>
  INSERT INTO pf_trait_table (name) VALUES ('divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_trait_action_association_table (action_id, trait_id) VALUES (v_action_id, 'divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Adaptive Strike', 'free', NULL, 'offensive', '<p>The naunet chooses adamantine, cold iron, or silver; its melee Strikes count as that type for 1 minute or until it uses Adaptive Strike again.</p>
  INSERT INTO pf_trait_table (name) VALUES ('divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_trait_action_association_table (action_id, trait_id) VALUES (v_action_id, 'divine') ON CONFLICT DO NOTHING;
  INSERT INTO pf_trait_table (name) VALUES ('polymorph') ON CONFLICT DO NOTHING;
