  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The naunet can take the appearance of any Small, Medium, or Large animal, beast, or humanoid. This doesn''t change its Speed or its attack and damage bonuses with its Strikes but might change the damage type its Strikes deal.</p><hr /><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'change-shape', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
