  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Confounding Slam', 'passive', NULL, 'offensive', '<p>A creature hit by the naunet''s tentacle Strike is Stupefied 2 for 1d4 rounds (will DC 25 negates). If the creature was already stupefied in this way, the duration extends by 1 round instead.</p>', 'OGL', FALSE, '', 'confounding-slam', '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
