  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Cloak of Souls', 'passive', NULL, 'interaction', '<p>An obcisidaemon is shrouded at all times in a cloak of captured souls. It can hold a number of souls equal to the daemon''s Charisma modifier. Destroying the daemon frees the souls, though this doesn''t return the deceased creatures to life. A creature whose soul is trapped within this cloak can''t be resurrected except by a 9th-rank Resurrect ritual or similarly powerful magic.</p>', 'OGL', FALSE, '', NULL, '') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
