  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Consume Fear', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The phasmadaemon has a creature Grabbed or Restrained</p><hr /><p><strong>Effect</strong> The phasmadaemon feeds on the creature''s mortality and innate terror, dealing 6d8 mental damage. The creature must attempt a will DC 38 save.</p><hr /><p><strong>Critical Success</strong> The creature takes no damage and manages to break free from the phasmadaemon''s Grab.</p>
