  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Clutching Armor', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature attempts to move away from the graveknight</p><hr /><p><strong>Effect</strong> The graveknight''s armor animates and attempts to Grab the triggering creature. It makes an Athletics check to Grapple using the graveknight''s Athletics modifier – 2.</p>
