-- ==== Ravener (g41X4b3q2iDMLRt3) ====
DO $mig$
DECLARE
  cr_id bigint;
  v_item_id bigint;
  v_sce_id bigint;
  v_range_id bigint;
  v_sense_id bigint;
  v_weakness_id bigint;
